#[repr(i32)]
pub enum TestMode {
    /// Read as TEST_MODE_LIVE.
    Unspecified = 0,
    Live = 1,
    /// Deterministic: the store is in memory, ids are fixed, and nothing on the
    /// device is read or written. UI suites run in it (WEBTIGER_FAKE=1).
    Fake = 2,
}
impl TestMode {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "TEST_MODE_UNSPECIFIED",
            Self::Live => "TEST_MODE_LIVE",
            Self::Fake => "TEST_MODE_FAKE",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "TEST_MODE_UNSPECIFIED" => Some(Self::Unspecified),
            "TEST_MODE_LIVE" => Some(Self::Live),
            "TEST_MODE_FAKE" => Some(Self::Fake),
            _ => None,
        }
    }
}
